// Calculer les dates du mois précédent
const now = new Date();
const firstDayLastMonth = new Date(now.getFullYear(), now.getMonth() - 1, 1);
const lastDayLastMonth = new Date(now.getFullYear(), now.getMonth(), 0);

const toISO = (d) => d.toISOString().split('T')[0];

const moisNoms = ['Janvier','Février','Mars','Avril','Mai','Juin','Juillet','Août','Septembre','Octobre','Novembre','Décembre'];
const nomMois = moisNoms[firstDayLastMonth.getMonth()];
const annee = firstDayLastMonth.getFullYear();

return [{
  json: {
    date_debut: toISO(firstDayLastMonth),
    date_fin: toISO(lastDayLastMonth),
    mois_label: `${nomMois} ${annee}`,
    annee: annee
  }
}];

// Construire le bilan mensuel
const periode = $('Calculer Période').first().json;
const searchResult = $input.first().json;
const documents = searchResult.results || [];

// Agréger par émetteur
const parEmetteur = {};
let totalMois = 0;
let facturesPayees = 0;
let facturesNonPayees = 0;
let totalNonPaye = 0;

for (const doc of documents) {
  const fields = doc.custom_fields || [];
  const getField = (name) => (fields.find(f => f.field === name) || {}).value ?? null;

  const emetteur = getField('emetteur') || 'Inconnu';
  const montant = parseFloat(getField('montant_total')) || 0;
  const statut = getField('statut_paiement') || 'Non Payé';

  if (!parEmetteur[emetteur]) {
    parEmetteur[emetteur] = { total: 0, count: 0, payes: 0, non_payes: 0 };
  }
  parEmetteur[emetteur].total += montant;
  parEmetteur[emetteur].count += 1;

  if (statut === 'Payé') {
    parEmetteur[emetteur].payes += 1;
    facturesPayees += 1;
  } else if (statut !== 'En Litige') {
    parEmetteur[emetteur].non_payes += 1;
    facturesNonPayees += 1;
    totalNonPaye += montant;
  }

  totalMois += montant;
}

// Trier par montant décroissant
const lignesEmetteurs = Object.entries(parEmetteur)
  .sort(([,a], [,b]) => b.total - a.total)
  .map(([emetteur, data]) => {
    const emoji = data.non_payes > 0 ? '⚠️' : '✅';
    return `${emoji} ${emetteur.padEnd(25)} ${data.total.toFixed(2).padStart(8)} € (${data.count} doc${data.count > 1 ? 's' : ''})`;
  })
  .join('\n');

const rapport = [
  `📊 BILAN easy-GED — ${periode.mois_label}`,
  `${'─'.repeat(45)}`,
  ``,
  `💶 Total factures : ${totalMois.toFixed(2)} €`,
  `✅ Payées         : ${facturesPayees}`,
  `⚠️  Non payées    : ${facturesNonPayees} (${totalNonPaye.toFixed(2)} €)`,
  `📄 Documents      : ${documents.length}`,
  ``,
  `Détail par émetteur :`,
  `${'─'.repeat(45)}`,
  lignesEmetteurs || '  Aucune facture ce mois',
  ``,
  `${'─'.repeat(45)}`,
  `easy-GED — Bilan automatique du 1er du mois`
].join('\n');

return [{
  json: {
    periode: periode.mois_label,
    total_mois: totalMois,
    factures_payees: facturesPayees,
    factures_non_payees: facturesNonPayees,
    total_non_paye: totalNonPaye,
    nb_documents: documents.length,
    rapport_texte: rapport,
    a_alerter: facturesNonPayees > 0
  }
}];
